-- Chile deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (SII)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los procedimientos de CAF, las especificaciones de TED y los cálculos de sanciones continúan evolucionando — confirme los requisitos actuales directamente con el SII antes de construir una integración.', 'Chile fue uno de los primeros países de América Latina en adoptar la facturación electrónica — el sistema es lo suficientemente maduro como para que la mayor parte de la actividad actual consista en ampliarlo (boleta, entrega digital) en lugar de construirlo.', 'El modelo DTE de Chile se apoya en dos pilares: la autorización de folios (CAF) que legitima sus números de factura, y el timbre electrónico (TED) que hace que cada documento sea verificable.', 'Un DTE solo adquiere validez legal una vez que el SII lo ha validado — se trata de un genuino modelo de compensación, no uno autocertificado.', 'La acreditación como emisor autorizado es un proceso de certificación genuino con el SII, no un registro autoservicio.', 'El riesgo práctico más agudo en Chile no es la multa en sí — es perder la capacidad de facturar por completo.' FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentralisiertes Clearing (SII)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. CAF-Verfahren, TED-Spezifikationen und Strafberechnungen entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt beim SII, bevor Sie eine Integration aufbauen.', 'Chile war eines der frühesten Länder Lateinamerikas bei der E-Rechnungsstellung — das System ist ausgereift genug, dass die meisten heutigen Aktivitäten seiner Erweiterung dienen (boleta, digitale Zustellung) statt seinem Aufbau.', 'Chiles DTE-Modell ruht auf zwei Säulen: der Folio-Autorisierung (CAF), die Ihre Rechnungsnummern legitimiert, und dem elektronischen Stempel (TED), der jedes Dokument verifizierbar macht.', 'Ein DTE wird erst rechtsgültig, sobald der SII es validiert hat — dies ist ein echtes Clearing-Modell, kein selbstzertifizierendes.', 'Die Akkreditierung als autorisierter Aussteller ist ein echter Zertifizierungsprozess mit dem SII, keine Selbstbedienungsanmeldung.', 'Das schärfste praktische Risiko in Chile ist nicht die Geldstrafe selbst — es ist der Verlust der Fähigkeit, überhaupt Rechnungen zu stellen.' FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (SII)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les procédures CAF, les spécifications TED et les calculs de sanctions continuent d''évoluer — confirmez les exigences actuelles directement auprès du SII avant de construire une intégration.', 'Le Chili a été l''un des premiers pays d''Amérique latine à adopter la facturation électronique — le système est suffisamment mature pour que l''essentiel de l''activité actuelle consiste à l''étendre (boleta, livraison numérique) plutôt qu''à le construire.', 'Le modèle DTE chilien repose sur deux piliers : l''autorisation de folio (CAF) qui légitime vos numéros de facture, et le timbre électronique (TED) qui rend chaque document vérifiable.', 'Un DTE ne devient légalement valide qu''une fois validé par le SII — il s''agit d''un véritable modèle de contrôle, pas d''un modèle auto-certifiant.', 'L''accréditation en tant qu''émetteur autorisé est un véritable processus de certification auprès du SII, pas une inscription en libre-service.', 'Le risque pratique le plus aigu au Chili n''est pas l''amende elle-même — c''est de perdre complètement la capacité de facturer.' FROM countries WHERE name_en = 'Chile';

