INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Tipos de documento', '[["33 / 34", "Factura Electrónica (afecta / exenta)"], ["39 / 41", "Boleta Electrónica (afecta / exenta)"], ["61", "Nota de Crédito"], ["Otros", "Nota de Débito, Guía de Despacho, facturas/notas de exportación"]]', 'Cada tipo de DTE se identifica por su propio código numérico — equivocarse aquí hace que el documento se procese como un tipo completamente distinto, no solo se marque para revisión.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Dokumenttypen', '[["33 / 34", "Factura Electrónica (steuerpflichtig / befreit)"], ["39 / 41", "Boleta Electrónica (steuerpflichtig / befreit)"], ["61", "Nota de Crédito"], ["Sonstige", "Nota de Débito, Guía de Despacho, Export-Rechnungen/-Notizen"]]', 'Jeder DTE-Typ wird durch seinen eigenen numerischen Code identifiziert — ein Fehler hier führt dazu, dass das Dokument vollständig als falscher Typ verarbeitet wird, nicht nur zur Überprüfung markiert.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Types de documents', '[["33 / 34", "Factura Electrónica (assujettie / exonérée)"], ["39 / 41", "Boleta Electrónica (assujettie / exonérée)"], ["61", "Nota de Crédito"], ["Autres", "Nota de Débito, Guía de Despacho, factures/notes d''exportation"]]', 'Chaque type de DTE est identifié par son propre code numérique — une erreur ici fait que le document est traité comme un type entièrement différent, pas simplement signalé pour révision.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'CAF — Código de Autorización de Folios', '[["Qué es", "Un archivo XML firmado por el SII que autoriza un rango de folios específico"], ["Solicitado a través de", "Portal web o API del SII, autenticado con un certificado digital"], ["Regla de folios", "Secuencial — no se puede omitir ni reutilizar"]]', 'A diferencia de sistemas donde la numeración de facturas es solo una convención interna, los números de folio de Chile son un recurso emitido por el gobierno del que se va descontando — agotarlos significa solicitar un nuevo CAF antes de poder emitir nada más.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'CAF — Código de Autorización de Folios', '[["Was es ist", "Eine vom SII signierte XML-Datei, die einen bestimmten Folio-Bereich autorisiert"], ["Beantragt über", "SII-Webportal oder API, authentifiziert mit einem digitalen Zertifikat"], ["Folio-Regel", "Fortlaufend — kann nicht übersprungen oder wiederverwendet werden"]]', 'Anders als in Systemen, in denen die Rechnungsnummerierung nur eine interne Konvention ist, sind Chiles Folio-Nummern eine staatlich ausgegebene Ressource, von der Sie abbuchen — geht sie zur Neige, müssen Sie einen neuen CAF beantragen, bevor Sie etwas Weiteres ausstellen können.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'CAF — Código de Autorización de Folios', '[["Ce que c''est", "Un fichier XML signé par le SII autorisant une plage de folios spécifique"], ["Demandé via", "Portail web ou API du SII, authentifié avec un certificat numérique"], ["Règle de folio", "Séquentiel — ne peut pas être sauté ou réutilisé"]]', 'Contrairement aux systèmes où la numérotation des factures n''est qu''une convention interne, les numéros de folio du Chili sont une ressource émise par le gouvernement sur laquelle vous puisez — l''épuiser signifie demander un nouveau CAF avant de pouvoir émettre quoi que ce soit d''autre.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'TED — Timbre Electrónico Digital', '[["Qué es", "Un timbre electrónico derivado de una cadena de datos cifrada"], ["Forma impresa", "Código de barras PDF417 en la representación visual"], ["Firma", "XMLDSig, usando un certificado digital personal acreditado"]]', 'Sin el TED y la firma XMLDSig, un DTE no tiene validez fiscal — no son complementos de integridad opcionales, son lo que hace que el documento sea legalmente una factura.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'TED — Timbre Electrónico Digital', '[["Was es ist", "Ein elektronischer Stempel, abgeleitet aus einer verschlüsselten Datenzeichenfolge"], ["Gedruckte Form", "PDF417-Barcode auf der visuellen Darstellung"], ["Signatur", "XMLDSig, mit einem akkreditierten persönlichen digitalen Zertifikat"]]', 'Ohne sowohl den TED als auch die XMLDSig-Signatur hat ein DTE keine steuerliche Gültigkeit — dies sind keine optionalen Integritätszusätze, sie machen das Dokument überhaupt erst rechtlich zu einer Rechnung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'TED — Timbre Electrónico Digital', '[["Ce que c''est", "Un timbre électronique dérivé d''une chaîne de données chiffrée"], ["Forme imprimée", "Code-barres PDF417 sur la représentation visuelle"], ["Signature", "XMLDSig, utilisant un certificat numérique personnel accrédité"]]', 'Sans le TED et la signature XMLDSig, un DTE n''a aucune validité fiscale — ce ne sont pas des ajouts d''intégrité optionnels, c''est ce qui fait légalement du document une facture.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificador obligatorio', '[["RUT", "Rol Único Tributario — formato XX.XXX.XXX-Y"], ["Dígito verificador", "Y, calculado con módulo 11"]]', 'Cada DTE debe llevar un RUT válido para ambas partes — valide el dígito verificador de módulo 11 antes del envío para detectar errores tipográficos que de otro modo causarían el rechazo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Pflichtidentifikator', '[["RUT", "Rol Único Tributario — Format XX.XXX.XXX-Y"], ["Prüfziffer", "Y, berechnet mit Modulo 11"]]', 'Jeder DTE muss eine gültige RUT für beide Parteien tragen — validieren Sie die Modulo-11-Prüfziffer vor der Übermittlung, um Tippfehler zu erkennen, die sonst zu einer Ablehnung führen würden.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identifiant obligatoire', '[["RUT", "Rol Único Tributario — format XX.XXX.XXX-Y"], ["Chiffre de contrôle", "Y, calculé avec modulo 11"]]', 'Chaque DTE doit porter un RUT valide pour les deux parties — validez le chiffre de contrôle modulo 11 avant soumission pour détecter les fautes de frappe qui entraîneraient sinon un rejet.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Conciliación mensual', '[["Sistema antiguo", "Libros de Compras y Ventas"], ["Sustituido por", "Formulario F29, prellenado a partir de los DTE emitidos/recibidos"], ["Fuente de datos", "RCV (Registro de Compras y Ventas)"]]', 'Dado que el F29 se nutre directamente de su actividad DTE, las discrepancias entre lo que ha emitido/recibido y lo que declara tienden a salir a la luz automáticamente — los datos DTE y la declaración de IVA están estrechamente vinculados en Chile.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Monatliche Abstimmung', '[["Altes System", "Bücher der Käufe und Verkäufe"], ["Ersetzt durch", "Formular F29, vorausgefüllt aus ausgestellten/empfangenen DTEs"], ["Datenquelle", "RCV (Registro de Compras y Ventas)"]]', 'Da das F29 direkt aus Ihrer DTE-Aktivität schöpft, treten Diskrepanzen zwischen dem, was Sie ausgestellt/empfangen haben, und dem, was Sie deklarieren, tendenziell automatisch zutage — DTE-Daten und Umsatzsteuererklärung sind in Chile eng gekoppelt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Rapprochement mensuel', '[["Ancien système", "Livres des achats et des ventes"], ["Remplacé par", "Formulaire F29, pré-rempli à partir des DTE émis/reçus"], ["Source des données", "RCV (Registro de Compras y Ventas)"]]', 'Comme le F29 s''appuie directement sur votre activité DTE, les écarts entre ce que vous avez émis/reçu et ce que vous déclarez ont tendance à apparaître automatiquement — les données DTE et la déclaration de TVA sont étroitement liées au Chili.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Acceso API para la gestión de CAF', '[["Entornos", "Modos separados de certificación y producción"], ["Autenticación", "Certificado digital perteneciente al titular del CAF o a un representante autorizado"]]', 'Existen pasarelas de terceros específicamente para permitir que los proveedores de software de facturación soliciten, almacenen y rastreen folios CAF de forma programática en lugar de mediante inicios de sesión manuales en el portal del SII.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'API-Zugriff für die CAF-Verwaltung', '[["Umgebungen", "Getrennte Zertifizierungs- und Produktionsmodi"], ["Authentifizierung", "Digitales Zertifikat des CAF-Inhabers oder eines autorisierten Vertreters"]]', 'Drittanbieter-Gateways existieren speziell, um Rechnungssoftware-Anbietern zu ermöglichen, CAF-Folios programmatisch anzufordern, zu speichern und nachzuverfolgen, statt über manuelle SII-Portal-Anmeldungen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Accès API pour la gestion des CAF', '[["Environnements", "Modes de certification et de production séparés"], ["Authentification", "Certificat numérique appartenant au titulaire du CAF ou à un représentant autorisé"]]', 'Des passerelles tierces existent spécifiquement pour permettre aux fournisseurs de logiciels de facturation de demander, stocker et suivre les folios CAF de manière programmatique plutôt que via des connexions manuelles au portail SII.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Modelo por lotes de boletas', '[["Tipo de documento", "Boleta Electrónica (39/41)"], ["Envío", "Requisitos simplificados, modelo por lotes para escenarios minoristas/POS"]]', 'Las boletas minoristas siguen un proceso de envío más ligero que las facturas completas — vale la pena saberlo si está desarrollando para punto de venta de alto volumen en lugar de facturación B2B.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Boleta-Batch-Modell', '[["Dokumenttyp", "Boleta Electrónica (39/41)"], ["Einreichung", "Vereinfachte Anforderungen, Batch-Modell für Einzelhandels-/POS-Szenarien"]]', 'Einzelhandels-Boletas folgen einem leichteren Einreichungsprozess als vollständige Facturas — wissenswert, wenn Sie für Hochvolumen-Kassensysteme statt für B2B-Rechnungsstellung entwickeln.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Modèle de lot de boletas', '[["Type de document", "Boleta Electrónica (39/41)"], ["Soumission", "Exigences simplifiées, modèle de lot pour les scénarios de vente au détail/POS"]]', 'Les boletas de détail suivent un processus de soumission plus léger que les facturas complètes — utile à savoir si vous construisez pour un point de vente à haut volume plutôt que pour la facturation B2B.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'El flujo de compensación', NULL, 'La solicitud de CAF ocurre una vez por rango de folios, no por factura — pero cada DTE individual sigue necesitando su propio TED, firma y envío al SII antes de ser válido.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Der Clearing-Ablauf', NULL, 'Die CAF-Anfrage erfolgt einmal pro Folio-Bereich, nicht pro Rechnung — aber jeder einzelne DTE benötigt weiterhin seinen eigenen TED, seine Signatur und die SII-Übermittlung, bevor er gültig ist.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Le flux de contrôle', NULL, 'La demande de CAF se fait une fois par plage de folios, pas par facture — mais chaque DTE individuel a toujours besoin de son propre TED, de sa signature et de sa soumission au SII avant d''être valide.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Chile';

