INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Complete el proceso de certificación de emisor del SII', 'Someta a pruebas de generación y recepción con el SII antes de estar acreditado para emitir DTE en producción.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Schließen Sie den Ausstellerzertifizierungsprozess des SII ab', 'Durchlaufen Sie Erstellungs- und Empfangstests mit dem SII, bevor Sie zur Ausstellung von DTEs in der Produktion akkreditiert sind.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Complétez le processus de certification d''émetteur du SII', 'Soumettez-vous à des tests de génération et de réception avec le SII avant d''être accrédité pour émettre des DTE en production.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga un certificado digital', 'Consiga su firma electrónica de un proveedor acreditado por el SII — esto es lo que autentica cada solicitud de CAF y firma cada DTE.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie ein digitales Zertifikat', 'Beziehen Sie Ihre firma electrónica von einem SII-akkreditierten Anbieter — dies authentifiziert jede CAF-Anfrage und signiert jeden DTE.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez un certificat numérique', 'Obtenez votre firma electrónica auprès d''un fournisseur accrédité par le SII — c''est ce qui authentifie chaque demande de CAF et signe chaque DTE.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Solicite sus rangos de folios CAF', 'Solicite a través del portal web o la API del SII para cada tipo de DTE que emitirá, autenticándose con su certificado digital.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beantragen Sie Ihre CAF-Folio-Bereiche', 'Beantragen Sie über das SII-Webportal oder die API für jeden DTE-Typ, den Sie ausstellen werden, mit Authentifizierung über Ihr digitales Zertifikat.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Demandez vos plages de folios CAF', 'Faites une demande via le portail web ou l''API du SII pour chaque type de DTE que vous émettrez, en vous authentifiant avec votre certificat numérique.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure su sistema para generar XML DTE válido', 'Incorpore el timbre electrónico TED y aplique la firma XMLDSig antes de cada envío — ambos son innegociables para la validez legal.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Konfigurieren Sie Ihr System zur Erzeugung gültiger DTE-XML', 'Betten Sie den elektronischen TED-Stempel ein und wenden Sie vor jeder Übermittlung die XMLDSig-Signatur an — beides ist für die Rechtsgültigkeit nicht verhandelbar.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Configurez votre système pour générer un XML DTE valide', 'Intégrez le timbre électronique TED et appliquez la signature XMLDSig avant chaque soumission — les deux sont non négociables pour la validité légale.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pruebe en el entorno de certificación del SII', 'Valide su flujo completo de emisión antes de pasar a producción — la mayoría de las pasarelas e integraciones admiten un modo de certificación dedicado exactamente para este propósito.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie in der Zertifizierungsumgebung des SII', 'Validieren Sie Ihren vollständigen Ausstellungsablauf, bevor Sie zur Produktion wechseln — die meisten Gateways und Integrationen unterstützen genau für diesen Zweck einen dedizierten Zertifizierungsmodus.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez dans l''environnement de certification du SII', 'Validez votre flux d''émission complet avant de passer en production — la plupart des passerelles et intégrations prennent en charge un mode de certification dédié exactement à cet effet.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure el archivo de 6 años y la conciliación F29', 'Construya la conciliación automatizada con la declaración RCV/F29 prellenada del SII, y archive los archivos XML DTE tanto emitidos como recibidos durante el período de conservación requerido.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie die 6-jährige Archivierung und die F29-Abstimmung ein', 'Bauen Sie eine automatisierte Abstimmung mit der vorausgefüllten RCV/F29-Erklärung des SII auf und archivieren Sie sowohl ausgestellte als auch empfangene DTE-XML-Dateien für die erforderliche Aufbewahrungsfrist.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage de 6 ans et un rapprochement F29', 'Construisez un rapprochement automatisé avec la déclaration RCV/F29 pré-remplie du SII, et archivez les fichiers XML DTE émis et reçus pendant la période de conservation requise.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su método de entrega de boletas para 2026', 'Si carece de impresión en el punto de venta, configure ahora un canal de entrega digital (correo electrónico, SMS, QR) en lugar de esperar a que una auditoría señale la brecha.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihre Boleta-Zustellmethode für 2026', 'Wenn Sie keinen Kassendrucker haben, richten Sie jetzt einen digitalen Zustellkanal ein (E-Mail, SMS, QR), anstatt zu warten, bis eine Prüfung die Lücke aufdeckt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez votre méthode de livraison de boletas pour 2026', 'Si vous n''avez pas d''impression au point de vente, mettez en place dès maintenant un canal de livraison numérique (e-mail, SMS, QR) plutôt qu''après qu''un audit signale la lacune.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Chile' AND ds.sort_order = 6;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '💸 Multas denominadas en UTM', NULL, NULL, 'El envío tardío o faltante de DTE al SII desencadena multas administrativas calculadas en UTM (Unidad Tributaria Mensual, una unidad fiscal mensual indexada a la inflación) más intereses — el valor en pesos cambia con la inflación, así que no se ancle a una cifra fija.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '💸 In UTM ausgedrückte Bußgelder', NULL, NULL, 'Verspätete oder fehlende DTE-Übermittlung an den SII löst administrative Bußgelder aus, berechnet in UTM (Unidad Tributaria Mensual, eine inflationsindexierte monatliche Steuereinheit) zuzüglich Zinsen — der Peso-Wert schwankt mit der Inflation, verankern Sie sich also nicht an einer festen Zahl.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '💸 Amendes libellées en UTM', NULL, NULL, 'Une transmission tardive ou manquante du DTE au SII déclenche des amendes administratives calculées en UTM (Unidad Tributaria Mensual, une unité fiscale mensuelle indexée sur l''inflation) plus des intérêts — la valeur en pesos évolue avec l''inflation, ne vous ancrez donc pas à un chiffre fixe.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🚫 Restricción de CAF — el verdadero elemento disuasorio', NULL, NULL, 'El incumplimiento repetido o las irregularidades pueden llevar al SII a restringir la capacidad de un contribuyente de descargar nuevos CAF — paralizando efectivamente su capacidad de emitir cualquier factura hasta que se resuelva la situación. Esta es una consecuencia mucho más disruptiva que la mayoría de los esquemas de multas de este rastreador.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🚫 CAF-Beschränkung — die eigentliche Abschreckung', NULL, NULL, 'Wiederholte Nichteinhaltung oder Unregelmäßigkeiten können dazu führen, dass der SII die Fähigkeit eines Steuerpflichtigen einschränkt, neue CAFs herunterzuladen — was seine Fähigkeit, überhaupt Rechnungen auszustellen, effektiv lahmlegt, bis die Situation gelöst ist. Dies ist eine weitaus disruptivere Konsequenz als die meisten Bußgeldregelungen in diesem Tracker.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🚫 Restriction du CAF — le véritable dissuasif', NULL, NULL, 'Une non-conformité répétée ou des irrégularités peuvent amener le SII à restreindre la capacité d''un contribuable à télécharger de nouveaux CAF — paralysant effectivement sa capacité à émettre la moindre facture jusqu''à résolution de la situation. C''est une conséquence bien plus perturbatrice que la plupart des barèmes d''amendes de ce tracker.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔗 El RCV como verificación cruzada automática', NULL, NULL, 'Dado que su declaración mensual de IVA F29 se prellena a partir del Registro de Compras y Ventas, las inconsistencias entre su actividad DTE y sus cifras declaradas tienden a salir a la luz sin necesidad de ser auditado primero.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔗 RCV als automatischer Abgleich', NULL, NULL, 'Da Ihre monatliche F29-Umsatzsteuererklärung aus dem Registro de Compras y Ventas vorausgefüllt wird, treten Unstimmigkeiten zwischen Ihrer DTE-Aktivität und Ihren deklarierten Zahlen tendenziell zutage, ohne dass Sie zuvor geprüft werden müssten.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔗 Le RCV comme vérification croisée automatique', NULL, NULL, 'Comme votre déclaration mensuelle de TVA F29 est pré-remplie à partir du Registro de Compras y Ventas, les incohérences entre votre activité DTE et vos chiffres déclarés ont tendance à apparaître sans que vous ayez besoin d''être audité au préalable.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🧾 Obligaciones relacionadas a seguir', NULL, NULL, 'El IVA sobre servicios digitales y la Guía de Despacho (guías de despacho para mercancías en tránsito) se encuentran ambos dentro de la misma familia DTE — confirme qué tipos de documentos adicionales se aplican a su actividad empresarial específica.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🧾 Zu verfolgende verwandte Pflichten', NULL, NULL, 'Umsatzsteuer auf digitale Dienstleistungen und Guía de Despacho (Versandbegleitscheine für Waren im Transit) gehören beide zur selben DTE-Familie — bestätigen Sie, welche zusätzlichen Dokumenttypen für Ihre spezifische Geschäftstätigkeit gelten.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🧾 Obligations connexes à suivre', NULL, NULL, 'La TVA sur les services numériques et le Guía de Despacho (guides d''expédition pour les marchandises en transit) relèvent tous deux de la même famille DTE — confirmez quels types de documents supplémentaires s''appliquent à votre activité commerciale spécifique.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

